CREATE TABLE IF NOT EXISTS `billing_checkouts` (`id` varchar(255) NOT NULL,`subject` varchar(300) NOT NULL,`plan_key` varchar(100) NOT NULL,`user_id` varchar(255) NOT NULL,`stripe_session_id` varchar(255),`status` varchar(20) NOT NULL,`redirect` varchar(500),`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`id`));
CREATE INDEX IF NOT EXISTS `idx_billing_checkouts_stripe_session_id` ON `billing_checkouts`(`stripe_session_id`);
CREATE INDEX IF NOT EXISTS `idx_billing_checkouts_subject` ON `billing_checkouts`(`subject`);
CREATE TABLE IF NOT EXISTS `billing_customers` (`subject` varchar(300) NOT NULL,`stripe_customer_id` varchar(255),`odoo_partner_id` integer,`name` varchar(255),`email` varchar(255),`tax_id` varchar(50),`address_line1` varchar(255),`address_line2` varchar(255),`postal_code` varchar(20),`city` varchar(100),`state` varchar(100),`country` varchar(2),`trial_groups` text,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`subject`));
CREATE INDEX IF NOT EXISTS `idx_billing_customers_stripe_customer_id` ON `billing_customers`(`stripe_customer_id`);
CREATE TABLE IF NOT EXISTS `billing_documents` (`id` varchar(255) NOT NULL,`subject` varchar(300) NOT NULL,`kind` varchar(20) NOT NULL,`stripe_ref` varchar(255) NOT NULL,`invoice_document_id` varchar(255),`subscription_id` varchar(255),`purchase_id` varchar(255),`amount_cents` integer NOT NULL,`currency` varchar(3) NOT NULL DEFAULT "eur",`lines` text NOT NULL,`paid_at` datetime NOT NULL,`odoo_move_id` integer,`odoo_state` varchar(20) NOT NULL,`odoo_error` text,`attempts` integer NOT NULL DEFAULT 0,`next_attempt_at` datetime NOT NULL,`number` varchar(100),`issued_at` datetime,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`id`));
CREATE INDEX IF NOT EXISTS `idx_billing_documents_next_attempt_at` ON `billing_documents`(`next_attempt_at`);
CREATE INDEX IF NOT EXISTS `idx_billing_documents_odoo_state` ON `billing_documents`(`odoo_state`);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_billing_documents_stripe_ref` ON `billing_documents`(`stripe_ref`);
CREATE INDEX IF NOT EXISTS `idx_billing_documents_subject` ON `billing_documents`(`subject`);
CREATE TABLE IF NOT EXISTS `billing_grants` (`id` varchar(255) NOT NULL,`subject` varchar(300) NOT NULL,`feature` varchar(100) NOT NULL,`until` datetime,`grace_days` integer,`note` text,`created_by` varchar(255),`created_at` datetime,PRIMARY KEY (`id`));
CREATE INDEX IF NOT EXISTS `idx_billing_grants_subject` ON `billing_grants`(`subject`);
CREATE TABLE IF NOT EXISTS `billing_plan_features` (`plan_key` varchar(100) NOT NULL,`feature` varchar(100) NOT NULL,PRIMARY KEY (`plan_key`,`feature`));
CREATE INDEX IF NOT EXISTS `idx_billing_plan_features_feature` ON `billing_plan_features`(`feature`);
CREATE TABLE IF NOT EXISTS `billing_plans` (`key` varchar(100) NOT NULL,`name` varchar(255) NOT NULL,`description` text,`kind` varchar(20) NOT NULL,`interval` varchar(10),`amount_cents` integer NOT NULL,`currency` varchar(3) NOT NULL DEFAULT "eur",`subject` varchar(10) NOT NULL DEFAULT "either",`trial_days` integer NOT NULL DEFAULT 0,`grace_days` integer NOT NULL DEFAULT 7,`setup_fee_cents` integer NOT NULL DEFAULT 0,`setup_fee_name` varchar(255),`starts` varchar(20) NOT NULL DEFAULT "on_payment",`access_days` integer NOT NULL DEFAULT 0,`collect_shipping` numeric NOT NULL DEFAULT false,`group_key` varchar(100),`active` numeric NOT NULL DEFAULT true,`stripe_product_id` varchar(255),`stripe_price_id` varchar(255),`stripe_first_period_price_id` varchar(255),`stripe_setup_fee_price_id` varchar(255),`odoo_product_id` integer,`odoo_setup_fee_product_id` integer,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`key`));
CREATE TABLE IF NOT EXISTS `billing_purchases` (`id` varchar(255) NOT NULL,`subject` varchar(300) NOT NULL,`plan_key` varchar(100) NOT NULL,`payer_user_id` varchar(255),`checkout_id` varchar(255),`subscription_id` varchar(255),`status` varchar(20) NOT NULL,`amount_cents` integer NOT NULL,`refunded_cents` integer NOT NULL DEFAULT 0,`currency` varchar(3) NOT NULL DEFAULT "eur",`stripe_payment_intent_id` varchar(255) NOT NULL,`paid_at` datetime NOT NULL,`shipping_name` varchar(255),`shipping_phone` varchar(50),`shipping_line1` varchar(255),`shipping_line2` varchar(255),`shipping_postal_code` varchar(20),`shipping_city` varchar(100),`shipping_state` varchar(100),`shipping_country` varchar(2),`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_billing_purchases_stripe_payment_intent_id` ON `billing_purchases`(`stripe_payment_intent_id`);
CREATE INDEX IF NOT EXISTS `idx_billing_purchases_plan_key` ON `billing_purchases`(`plan_key`);
CREATE INDEX IF NOT EXISTS `idx_billing_purchases_subject` ON `billing_purchases`(`subject`);
CREATE TABLE IF NOT EXISTS `billing_subscriptions` (`id` varchar(255) NOT NULL,`subject` varchar(300) NOT NULL,`plan_key` varchar(100) NOT NULL,`payer_user_id` varchar(255),`status` varchar(30) NOT NULL,`stripe_subscription_id` varchar(255),`stripe_payment_method_id` varchar(255),`current_period_end` datetime,`trial_end` datetime,`cancel_at_period_end` numeric NOT NULL DEFAULT false,`grace_until` datetime,`activated_at` datetime,`canceled_at` datetime,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_billing_subscriptions_stripe_subscription_id` ON `billing_subscriptions`(`stripe_subscription_id`);
CREATE INDEX IF NOT EXISTS `idx_billing_subscriptions_subject` ON `billing_subscriptions`(`subject`);
CREATE TABLE IF NOT EXISTS `organization_members` (`organization_id` varchar(255) NOT NULL,`user_id` varchar(255) NOT NULL,`role` varchar(20) NOT NULL,`created_at` datetime,PRIMARY KEY (`organization_id`,`user_id`));
CREATE INDEX IF NOT EXISTS `idx_organization_members_user_id` ON `organization_members`(`user_id`);
CREATE TABLE IF NOT EXISTS `organizations` (`id` varchar(255) NOT NULL,`name` varchar(255) NOT NULL,`logo` blob,`logo_content_type` varchar(50),`logo_updated_at` datetime,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `stripe_events` (`event_id` varchar(255) NOT NULL,`type` varchar(100) NOT NULL,`received_at` datetime,PRIMARY KEY (`event_id`));
CREATE TABLE IF NOT EXISTS `stuck_stripe_events` (`event_id` varchar(255) NOT NULL,`type` varchar(100) NOT NULL,`subscription_id` varchar(255) NOT NULL,`reason` text NOT NULL,`attempts` integer NOT NULL,`first_seen_at` datetime NOT NULL,`last_seen_at` datetime NOT NULL,PRIMARY KEY (`event_id`));
